create table if not exists knowledge_bases (id uuid primary key, name varchar(120) not null, description varchar(1000), owner_id uuid not null, status varchar(24) not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
create table if not exists source_documents (id uuid primary key, knowledge_base_id uuid not null references knowledge_bases(id), original_name varchar(255) not null, media_type varchar(120), storage_key varchar(500) not null, size_bytes bigint not null, status varchar(24) not null, parse_mode varchar(32), created_at timestamp with time zone not null);
create table if not exists document_chunks (id uuid primary key, document_id uuid not null references source_documents(id), chunk_index integer not null, content text not null, source_ref varchar(255), embedding jsonb, created_at timestamp with time zone not null);
create table if not exists occupational_standards (id uuid primary key, document_id uuid references source_documents(id), profession varchar(120) not null, occupation_code varchar(64), status varchar(24) not null, schema_json text not null, version integer not null, created_at timestamp with time zone not null);
create table if not exists generation_jobs (id uuid primary key, job_type varchar(40) not null, status varchar(24) not null, progress integer not null, request_json text not null, result_json text, retry_count integer not null, created_at timestamp with time zone not null, updated_at timestamp with time zone not null);
